import ops from "@/illustrations/generated/ops.json";
import { LayeredVector } from "./LayeredVector";

// The plant for the homepage problem section, generated by `npm run build:illustrations`
// (illustrations/model/ops.ts). Its animated parts follow the `.ops` styles.
export function OpsVector({ label, className }: { label: string; className?: string }) {
  return <LayeredVector scene={ops} label={label} className={className} />;
}

// The model's named anchors as positions over the drawing, in percent, so the page can zoom to a
// zone and pin labels to machines at any size.
export function opsAnchors(): Record<string, { x: number; y: number }> {
  const [x0, y0, width, height] = ops.viewBox;
  return Object.fromEntries(
    Object.entries(ops.anchors as Record<string, number[]>).map(([name, [x, y]]) => [name, { x: Math.round(((x - x0) / width) * 1000) / 10, y: Math.round(((y - y0) / height) * 1000) / 10 }]),
  );
}
